'use strict';
const memoData=window.QUIZ_DATA.filter(a=>a.category==='speaking-t1').sort((a,b)=>(b.frequency||0)-(a.frequency||0));
const memoEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const memoContainer=document.querySelector('#memo-articles');
memoContainer.innerHTML=memoData.map((a,i)=>`<article id="memo-${i+1}" class="card memo-article"><div class="meta"><span class="badge">${String(i+1).padStart(2,'0')}</span><span>出现 ${a.frequency} 次 · ${a.passage.length} 句</span><a href="#memo-toc">回目录</a></div><h2>${memoEscape(a.title)}</h2><p class="subtitle">${memoEscape(a.titleZh)}</p><div class="memo-notes"><p>${memoEscape(a.summary)}</p><p>${memoEscape(a.tips)}</p></div><ol class="memo-sentences">${a.passage.map(([en,zh])=>`<li><p class="memo-en">${memoEscape(en)}</p><p class="memo-zh">${memoEscape(zh)}</p><button class="memo-reveal" aria-expanded="false">查看原句</button></li>`).join('')}</ol><details><summary>出现日期</summary>${memoEscape(a.dates.join(' · '))}</details></article>`).join('');
document.querySelector('#memo-toc').innerHTML=memoData.map((a,i)=>`<a href="#memo-${i+1}" data-index="${i}" class="article-link">${String(i+1).padStart(2,'0')}　${memoEscape(a.titleZh)}<small>${memoEscape(a.title)}</small></a>`).join('');
let language='both';
function setLanguage(value){language=value;memoContainer.className='language-'+value;memoContainer.querySelectorAll('li.revealed').forEach(li=>li.classList.remove('revealed'));memoContainer.querySelectorAll('.memo-reveal').forEach(b=>{b.textContent='查看原句';b.setAttribute('aria-expanded','false')});document.querySelectorAll('[data-language]').forEach(b=>{b.classList.toggle('primary',b.dataset.language===value);b.setAttribute('aria-pressed',String(b.dataset.language===value))})}
document.querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>setLanguage(b.dataset.language));
memoContainer.addEventListener('click',e=>{const b=e.target.closest('.memo-reveal');if(!b)return;const visible=b.closest('li').classList.toggle('revealed');b.textContent=visible?'收起原句':'查看原句';b.setAttribute('aria-expanded',String(visible))});
document.querySelector('#memo-notes').onchange=e=>document.body.classList.toggle('notes-hidden',!e.target.checked);
function filterArticles(){const term=document.querySelector('#memo-search').value.trim().toLowerCase();let count=0,sentences=0;memoData.forEach((a,i)=>{const match=(!term||[a.title,a.titleZh,...a.passage.flat()].join(' ').toLowerCase().includes(term));document.querySelector('#memo-'+(i+1)).hidden=!match;document.querySelector(`[data-index="${i}"]`).hidden=!match;if(match){count++;sentences+=a.passage.length}});document.querySelector('#memo-count').textContent=count?`已展开 ${count} 篇 · ${sentences} 句`:'没有匹配的内容，请换个关键词。'}
document.querySelector('#memo-search').oninput=filterArticles;filterArticles();
